-- Anaira Clinic OPD reception parchi, configurable validity/fee, optional doctor assignment and queue.
create table if not exists public.opd_visits (
 id uuid primary key default gen_random_uuid(), clinic_id uuid not null references public.clinics(id) on delete cascade,
 branch_id uuid references public.clinic_branches(id) on delete set null, patient_id uuid not null references public.patients(id),
 visit_no text not null, complaint text not null, department text not null, doctor_name text not null,
 doctor_user_id uuid references auth.users(id) on delete set null, notify_doctor boolean not null default false, notified_at timestamptz,
 validity_days integer not null default 7 check(validity_days between 1 and 365), issued_at timestamptz not null default now(), valid_until date not null,
 registration_fee numeric(12,2) not null default 0 check(registration_fee>=0), invoice_id uuid references public.invoices(id) on delete set null,
 status text not null default 'waiting' check(status in ('waiting','called','in_consultation','sent_to_lab','sent_to_pharmacy','admission_pending','completed','cancelled','expired')),
 notes text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(clinic_id,visit_no));
alter table public.opd_visits enable row level security;
drop policy if exists opd_visits_select_clinic_role on public.opd_visits;
create policy opd_visits_select_clinic_role on public.opd_visits for select to authenticated using ((private.has_clinic_role(clinic_id,array['owner','admin','receptionist','nurse','lab_technician','pharmacist','accountant'])) or (private.has_clinic_role(clinic_id,array['doctor']) and doctor_user_id=(select auth.uid())));
drop policy if exists opd_visits_update_clinic_role on public.opd_visits;
create policy opd_visits_update_clinic_role on public.opd_visits for update to authenticated using ((private.has_clinic_role(clinic_id,array['owner','admin','receptionist'])) or (private.has_clinic_role(clinic_id,array['doctor']) and doctor_user_id=(select auth.uid()))) with check ((private.has_clinic_role(clinic_id,array['owner','admin','receptionist'])) or (private.has_clinic_role(clinic_id,array['doctor']) and doctor_user_id=(select auth.uid())));
create index if not exists opd_visits_clinic_day_idx on public.opd_visits(clinic_id,issued_at desc);
create index if not exists opd_visits_doctor_queue_idx on public.opd_visits(clinic_id,doctor_user_id,status,issued_at desc);
create or replace function public.set_clinic_opd_policy(p_clinic_id uuid,p_validity_days integer,p_registration_fee numeric) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); begin if v_user is null then raise exception 'Authentication required'; end if; if not private.has_clinic_role(p_clinic_id,array['owner','admin']) then raise exception 'Only clinic owner/admin can change OPD parchi settings'; end if; if p_validity_days<1 or p_validity_days>365 then raise exception 'Validity must be between 1 and 365 days'; end if; if p_registration_fee is null or p_registration_fee<0 or p_registration_fee>1000000 then raise exception 'Registration fee must be between 0 and 1000000'; end if; insert into public.clinic_settings(clinic_id,settings,updated_by,updated_at) values(p_clinic_id,jsonb_build_object('opd_parchi_validity_days',p_validity_days,'opd_registration_fee',p_registration_fee),v_user,now()) on conflict(clinic_id) do update set settings=public.clinic_settings.settings || jsonb_build_object('opd_parchi_validity_days',p_validity_days,'opd_registration_fee',p_registration_fee),updated_by=v_user,updated_at=now(); insert into public.audit_logs(clinic_id,actor_user_id,action,entity_type,details) values(p_clinic_id,v_user,'update_opd_parchi_policy','clinic_settings',jsonb_build_object('validity_days',p_validity_days,'registration_fee',p_registration_fee)); return jsonb_build_object('validity_days',p_validity_days,'registration_fee',p_registration_fee); end $$;
revoke all on function public.set_clinic_opd_policy(uuid,integer,numeric) from public,anon; grant execute on function public.set_clinic_opd_policy(uuid,integer,numeric) to authenticated;
create or replace function public.create_clinic_opd_visit(p_clinic_id uuid,p_patient_id uuid,p_complaint text,p_department text,p_doctor_name text,p_doctor_user_id uuid default null,p_notify_doctor boolean default false,p_branch_id uuid default null,p_collect_registration_fee boolean default true,p_payment_method text default 'cash') returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); v_days integer:=7; v_fee numeric:=0; v_id uuid:=gen_random_uuid(); v_no text; v_until date; v_invoice uuid; v_invoice_no text; v_status text; begin if v_user is null then raise exception 'Authentication required'; end if; if not private.has_clinic_role(p_clinic_id,array['owner','admin','receptionist']) then raise exception 'Reception/clinic admin permission required'; end if; if length(trim(coalesce(p_complaint,'')))<2 then raise exception 'Please record the patient complaint'; end if; if length(trim(coalesce(p_department,'')))<2 then raise exception 'Select the department'; end if; if length(trim(coalesce(p_doctor_name,'')))<2 then raise exception 'Select or enter the doctor'; end if; if not exists(select 1 from public.patients p where p.id=p_patient_id and p.clinic_id=p_clinic_id and p.archived_at is null) then raise exception 'Patient is not registered in this clinic'; end if; if p_branch_id is not null and not exists(select 1 from public.clinic_branches b where b.id=p_branch_id and b.clinic_id=p_clinic_id and b.active=true) then raise exception 'Branch does not belong to this clinic'; end if; if p_doctor_user_id is not null and not exists(select 1 from public.staff_profiles s join public.clinic_members m on m.clinic_id=s.clinic_id and m.user_id=s.user_id and m.active=true where s.clinic_id=p_clinic_id and s.user_id=p_doctor_user_id and s.role='doctor' and s.active=true) then raise exception 'Selected doctor login is not active in this clinic'; end if; if p_payment_method not in ('cash','card','upi','bank_transfer','insurance','other') then raise exception 'Unsupported payment method'; end if; select greatest(1,least(365,coalesce(nullif(settings->>'opd_parchi_validity_days','')::integer,7))), greatest(0,coalesce(nullif(settings->>'opd_registration_fee','')::numeric,0)) into v_days,v_fee from public.clinic_settings where clinic_id=p_clinic_id; v_days:=coalesce(v_days,7);v_fee:=coalesce(v_fee,0);v_until:=(now() at time zone 'Asia/Kolkata')::date+v_days-1;v_no:='OPD-'||to_char(now() at time zone 'Asia/Kolkata','YYYYMMDD')||'-'||upper(substr(replace(v_id::text,'-',''),1,8)); if v_fee>0 then v_invoice:=gen_random_uuid();v_invoice_no:='REG-'||to_char(now() at time zone 'Asia/Kolkata','YYYYMMDD')||'-'||upper(substr(replace(v_invoice::text,'-',''),1,8));v_status:=case when p_collect_registration_fee then 'paid' else 'issued' end; insert into public.invoices(id,clinic_id,branch_id,patient_id,invoice_no,status,subtotal,total_amount,paid_amount,issued_at,created_by) values(v_invoice,p_clinic_id,p_branch_id,p_patient_id,v_invoice_no,v_status,v_fee,v_fee,case when p_collect_registration_fee then v_fee else 0 end,now(),v_user); insert into public.invoice_items(clinic_id,invoice_id,item_type,description,quantity,unit_price,line_total) values(p_clinic_id,v_invoice,'service','OPD registration / parchi fee',1,v_fee,v_fee); if p_collect_registration_fee then insert into public.payments(clinic_id,invoice_id,patient_id,amount,method,status,received_by,paid_at) values(p_clinic_id,v_invoice,p_patient_id,v_fee,p_payment_method,'completed',v_user,now()); end if; end if; insert into public.opd_visits(id,clinic_id,branch_id,patient_id,visit_no,complaint,department,doctor_name,doctor_user_id,notify_doctor,notified_at,validity_days,valid_until,registration_fee,invoice_id,status,created_by) values(v_id,p_clinic_id,p_branch_id,p_patient_id,v_no,trim(p_complaint),trim(p_department),trim(p_doctor_name),p_doctor_user_id,coalesce(p_notify_doctor,false) and p_doctor_user_id is not null,case when coalesce(p_notify_doctor,false) and p_doctor_user_id is not null then now() else null end,v_days,v_until,v_fee,v_invoice,'waiting',v_user); if p_doctor_user_id is not null and coalesce(p_notify_doctor,false) then insert into public.audit_logs(clinic_id,actor_user_id,action,entity_type,entity_id,details) values(p_clinic_id,v_user,'notify_doctor_new_opd_visit','opd_visit',v_id::text,jsonb_build_object('doctor_user_id',p_doctor_user_id,'visit_no',v_no,'patient_id',p_patient_id)); end if; insert into public.audit_logs(clinic_id,actor_user_id,action,entity_type,entity_id,details) values(p_clinic_id,v_user,'create_opd_parchi','opd_visit',v_id::text,jsonb_build_object('visit_no',v_no,'patient_id',p_patient_id,'department',p_department,'doctor_name',p_doctor_name,'valid_until',v_until,'registration_fee',v_fee,'invoice_id',v_invoice)); return jsonb_build_object('id',v_id,'visit_no',v_no,'patient_id',p_patient_id,'department',p_department,'doctor_name',p_doctor_name,'doctor_user_id',p_doctor_user_id,'notify_doctor',coalesce(p_notify_doctor,false) and p_doctor_user_id is not null,'validity_days',v_days,'valid_until',v_until,'registration_fee',v_fee,'invoice_id',v_invoice,'invoice_no',v_invoice_no,'invoice_status',v_status,'status','waiting'); end $$;
revoke all on function public.create_clinic_opd_visit(uuid,uuid,text,text,text,uuid,boolean,uuid,boolean,text) from public,anon; grant execute on function public.create_clinic_opd_visit(uuid,uuid,text,text,text,uuid,boolean,uuid,boolean,text) to authenticated;
create or replace function public.doctor_opd_queue(p_clinic_id uuid) returns table(id uuid,visit_no text,patient_id uuid,patient_name text,uhid text,phone text,complaint text,department text,doctor_name text,issued_at timestamptz,valid_until date,status text,registration_fee numeric) language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); begin if v_user is null then raise exception 'Authentication required'; end if; if not private.has_clinic_role(p_clinic_id,array['owner','admin','doctor']) then raise exception 'Doctor queue access denied'; end if; return query select o.id,o.visit_no,o.patient_id,concat_ws(' ',p.first_name,p.middle_name,p.last_name),p.uhid,p.phone,o.complaint,o.department,o.doctor_name,o.issued_at,o.valid_until,o.status,o.registration_fee from public.opd_visits o join public.patients p on p.id=o.patient_id and p.clinic_id=o.clinic_id where o.clinic_id=p_clinic_id and (private.has_clinic_role(p_clinic_id,array['owner','admin']) or o.doctor_user_id=v_user) and o.status not in ('completed','cancelled','expired') order by o.issued_at asc limit 500; end $$;
revoke all on function public.doctor_opd_queue(uuid) from public,anon; grant execute on function public.doctor_opd_queue(uuid) to authenticated;
